--- Compare a single TrigText value against an objective text.
-- Supports percentage thresholds ("50%"), ratio comparisons ("2/6"), and plain substring matching.
-- @param trigValue string The trigger value from the step (e.g. "1/3", "50%", or literal text).
-- @param objectiveText string The current objective text from the quest log.
-- @param currentPercent number|nil Optional progress bar percentage for threshold triggers.
-- @return boolean True if the objective text satisfies the trigger condition.
function APR:TrigTextValueMatch(trigValue, objectiveText, currentPercent)
    if not trigValue or not objectiveText then return false end

    local trigStr = tostring(trigValue)

    -- Percentage threshold: "50%"
    local wanted = trigStr:match("(%d+)%s*%%")
    if wanted and currentPercent then
        wanted = tonumber(wanted)
        if wanted and currentPercent >= wanted then
            return true
        end
    end

    -- Partial source objectives may not provide a verified total. "X/" means
    -- at least X in the displayed counter, using the existing TrigText field.
    local threshold = trigStr:match("^(%d+)/$")
    if threshold then
        for current in tostring(objectiveText):gmatch("(%d+)%s*/%s*%d+") do
            if tonumber(current) >= tonumber(threshold) then return true end
        end
        return false
    end

    -- Ratio comparison: "X/Y" matches when objective shows "A/Y" with A >= X
    local trigNum, trigDenom = trigStr:match("^(%d+)/(%d+)$")
    if trigNum and trigDenom then
        trigNum = tonumber(trigNum)
        trigDenom = tonumber(trigDenom)
        for currentNum, currentDenom in tostring(objectiveText):gmatch("(%d+)/(%d+)") do
            if tonumber(currentDenom) == trigDenom and tonumber(currentNum) >= trigNum then
                return true
            end
        end
    end

    -- Plain substring match
    return self:ContainsText(objectiveText, trigValue)
end--[[APR_DIAG]]; APR.TrigTextValueMatch = APRTrace("APR-Core/utils/QuestUtils.lua:526:APR:TrigTextValueMatch#34", APR.TrigTextValueMatch)--[[/APR_DIAG]]

--- Checks if the provided objective text matches the trigger text for a specific quest part.
-- @param step The current step or stage in the quest sequence.
-- @param questID The unique identifier for the quest.
-- @param objectiveText The text of the quest objective to be matched.
-- @return boolean True if the objective text matches the trigger, false otherwise.
function APR:QpartPart_TrigTextMatch(step, questID, objectiveText)
    if not step then return false end

    local currentPercent = GetQuestProgressPercentSafe(questID)

    for key, value in pairs(step) do
        if type(key) == "string" and string.match(key, "^TrigText%d*$") and value and objectiveText then
            if self:TrigTextValueMatch(value, objectiveText, currentPercent) then
                return true
            end
        end
    end

    return false
end--[[APR_DIAG]]; APR.QpartPart_TrigTextMatch = APRTrace("APR-Core/utils/QuestUtils.lua:571:APR:QpartPart_TrigTextMatch#35", APR.QpartPart_TrigTextMatch)--[[/APR_DIAG]]

--- Returns scenario criteria text with progress when available.
-- Example output: "Collect Crystals (2/6)" when quantityString exists.
-- @param scenario table Scenario reference from step.Scenario.
-- @return string|nil Scenario criteria label for UI/matching.
function APR:GetScenarioCriteriaProgressText(scenario)
    if not scenario or not scenario.stepID or not scenario.criteriaIndex then
        return nil
    end

    local criteriaInfo = C_ScenarioInfo.GetCriteriaInfoByStep(scenario.stepID, scenario.criteriaIndex)
    if not criteriaInfo then
        return nil
    end

    local description = criteriaInfo.description
    local quantityString = criteriaInfo.quantityString

    if quantityString and quantityString ~= "" then
        if description and description ~= "" then
            return description .. " (" .. quantityString .. ")"
        end
        return quantityString
    end

    return description
end--[[APR_DIAG]]; APR.GetScenarioCriteriaProgressText = APRTrace("APR-Core/utils/QuestUtils.lua:591:APR:GetScenarioCriteriaProgressText#36", APR.GetScenarioCriteriaProgressText)--[[/APR_DIAG]]

--- Checks TrigText conditions for a scenario step using live scenario criteria data.
-- Supports exact/substring text, X/Y ratios, and percentage thresholds.
-- @param step table Current route step.
-- @param scenario table Scenario payload from step.Scenario.
-- @return boolean True when any TrigText key matches current scenario progress.
function APR:IsScenarioTrigTextMatched(step, scenario)
    if not step or not scenario or not scenario.stepID or not scenario.criteriaIndex then
        return false
    end

    local criteriaInfo = C_ScenarioInfo.GetCriteriaInfoByStep(scenario.stepID, scenario.criteriaIndex)
    if not criteriaInfo then
        return false
    end

    local description = criteriaInfo.description
    local quantityString = criteriaInfo.quantityString
    local currentQuantity = criteriaInfo.quantity
    if type(currentQuantity) ~= "number" then
        currentQuantity = rawget(criteriaInfo, "amount") or rawget(criteriaInfo, "completedQuantity")
    end

    local totalQuantity = criteriaInfo.totalQuantity
    if type(totalQuantity) ~= "number" then
        totalQuantity = rawget(criteriaInfo, "requiredQuantity") or rawget(criteriaInfo, "maxQuantity")
    end

    local currentPercent = nil
    if type(currentQuantity) == "number" and type(totalQuantity) == "number" and totalQuantity > 0 then
        currentPercent = math.floor((currentQuantity / totalQuantity) * 100)
    end

    local objectiveCandidates = {}
    if quantityString and quantityString ~= "" then
        table.insert(objectiveCandidates, quantityString)
    end
    if description and description ~= "" then
        table.insert(objectiveCandidates, description)
    end
    if description and description ~= "" and quantityString and quantityString ~= "" then
        table.insert(objectiveCandidates, description .. " (" .. quantityString .. ")")
    end
    if type(currentQuantity) == "number" and type(totalQuantity) == "number" and totalQuantity > 0 then
        table.insert(objectiveCandidates, tostring(currentQuantity) .. "/" .. tostring(totalQuantity))
    end

    if #objectiveCandidates == 0 then
        return false
    end

    for key, value in pairs(step) do
        if type(key) == "string" and string.match(key, "^TrigText%d*$") and value then
            for _, objectiveText in ipairs(objectiveCandidates) do
                if self:TrigTextValueMatch(value, objectiveText, currentPercent) then
                    return true
                end
            end
        end
    end

    return false
end--[[APR_DIAG]]; APR.IsScenarioTrigTextMatched = APRTrace("APR-Core/utils/QuestUtils.lua:619:APR:IsScenarioTrigTextMatched#37", APR.IsScenarioTrigTextMatched)--[[/APR_DIAG]]

-- QuestCache owns this synchronous scope. Never revive it after observing a
-- different context, even if the caller later restores the old identities.
local function IsQuestObjectiveSnapshotCurrent(self, snapshot)
    if not snapshot or snapshot.invalid then return false end
    local player, route = self.PlayerID, self.ActiveRoute
    local progress = APRData and player and APRData[player]
    local current = self._questObjectiveSnapshot == snapshot
        and snapshot.player == player and snapshot.quests == self.ActiveQuests
        and snapshot.route == route and snapshot.progress == progress
        and snapshot.index == (progress and route and progress[route])
        and snapshot.revision == (self.stepRevision or 0)
        and snapshot.definition == (route and self.RouteQuestStepList and self.RouteQuestStepList[route])
    if not current then snapshot.invalid = true end
    return current
end--[[APR_DIAG]]; IsQuestObjectiveSnapshotCurrent = APRTrace("APR-Core/utils/QuestUtils.lua:679:IsQuestObjectiveSnapshotCurrent#38", IsQuestObjectiveSnapshotCurrent)--[[/APR_DIAG]]

local function ReadQuestObjectiveSnapshot(self, questID)
    local snapshot = self._questObjectiveSnapshot
    if IsQuestObjectiveSnapshotCurrent(self, snapshot) and snapshot[questID] ~= nil then
        return snapshot[questID] or nil
    end

    local getObjectives = C_QuestLog and C_QuestLog.GetQuestObjectives
    if not getObjectives then return nil end
    local objectives = getObjectives(questID)
    -- A native call can reenter UpdateQuest or change the route. Only a
    -- successful read in the same still-valid scope may populate a miss.
    if IsQuestObjectiveSnapshotCurrent(self, snapshot) then
        snapshot[questID] = objectives or false
    end
    return objectives
end--[[APR_DIAG]]; ReadQuestObjectiveSnapshot = APRTrace("APR-Core/utils/QuestUtils.lua:693:ReadQuestObjectiveSnapshot#39", ReadQuestObjectiveSnapshot)--[[/APR_DIAG]]

--- Returns a percentage only for a progress-bar objective in an active quest.
function APR:GetQuestObjectiveProgressPercent(questId, objectiveId)
    questId, objectiveId = tonumber(questId), tonumber(objectiveId)
    local quest = questId and self.ActiveQuests and self.ActiveQuests[questId]
    if not quest or not quest.objectives or not quest.objectives[objectiveId]
        or not C_QuestLog or not C_QuestLog.GetQuestObjectives then
        IsQuestObjectiveSnapshotCurrent(self, self._questObjectiveSnapshot)
        return nil
    end

    local objectives = ReadQuestObjectiveSnapshot(self, questId)
    local objective = objectives and objectives[objectiveId]
    if not objective or objective.type ~= "progressbar" then return nil end

    local percent = GetQuestProgressPercentSafe(questId)
    if percent then return math.max(0, math.min(100, percent)) end
end--[[APR_DIAG]]; APR.GetQuestObjectiveProgressPercent = APRTrace("APR-Core/utils/QuestUtils.lua:711:APR:GetQuestObjectiveProgressPercent#40", APR.GetQuestObjectiveProgressPercent)--[[/APR_DIAG]]

--- Retrieves the quest text associated with a specific progress bar objective.
-- @param questId number The unique identifier of the quest.
-- @param objectiveId number The identifier of the specific objective within the quest.
-- @return string The text description for the progress bar objective, or nil if not found.
function APR:GetQuestTextForProgressBar(questId, objectiveId)
    if not questId or not objectiveId then
        IsQuestObjectiveSnapshotCurrent(self, self._questObjectiveSnapshot)
        return
    end

    local questData = self.ActiveQuests and self.ActiveQuests[questId]
    if not questData or not questData.objectives then
        IsQuestObjectiveSnapshotCurrent(self, self._questObjectiveSnapshot)
        return
    end

    local objective = questData.objectives[objectiveId]
    if not objective then
        IsQuestObjectiveSnapshotCurrent(self, self._questObjectiveSnapshot)
        return
    end

    local questText = objective.text
    if not questText or string.find(questText, "%d") then
        -- Early returns still observe context changes, without a native read.
        IsQuestObjectiveSnapshotCurrent(self, self._questObjectiveSnapshot)
        return questText
    end

    local checkpbar = ReadQuestObjectiveSnapshot(self, questId)
    if checkpbar and checkpbar[objectiveId] and checkpbar[objectiveId].type == "progressbar" then
        local progress = GetQuestProgressPercentSafe(questId)
        if progress then
            questText = questText .. " (" .. progress .. "%)"
        end
    end
    return questText
end--[[APR_DIAG]]; APR.GetQuestTextForProgressBar = APRTrace("APR-Core/utils/QuestUtils.lua:732:APR:GetQuestTextForProgressBar#41", APR.GetQuestTextForProgressBar)--[[/APR_DIAG]]
